package com.example.complaintmanagement.service.impl; import com.example.complaintmanagement.dto.UserDtos.*; import com.example.complaintmanagement.entity.*; import com.example.complaintmanagement.exception.*; import com.example.complaintmanagement.mapper.UserMapper; import com.example.complaintmanagement.repository.UserRepository; import com.example.complaintmanagement.service.UserService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*;
@Service public class UserServiceImpl implements UserService {final UserRepository r;final PasswordEncoder e;final UserMapper m=new UserMapper(); public UserServiceImpl(UserRepository r,PasswordEncoder e){this.r=r;this.e=e;} public List<UserResponse> all(){return r.findAll().stream().map(m::toResponse).toList();} public UserResponse get(Long id){return m.toResponse(r.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found with id: "+id)));} public UserResponse create(CreateRequest x){if(r.existsByUsername(x.username()))throw new BadRequestException("Username already exists");if(r.existsByEmail(x.email()))throw new BadRequestException("Email already registered");return m.toResponse(r.save(User.builder().firstName(x.firstName()).lastName(x.lastName()).username(x.username()).email(x.email()).password(e.encode(x.password())).role(x.role()).active(true).createdAt(LocalDateTime.now()).build()));} public UserResponse update(Long id,UpdateRequest x){User u=r.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found with id: "+id));u.setFirstName(x.firstName());u.setLastName(x.lastName());u.setEmail(x.email());u.setRole(x.role());u.setActive(x.active());return m.toResponse(r.save(u));} public void delete(Long id){if(!r.existsById(id))throw new ResourceNotFoundException("User not found with id: "+id);r.deleteById(id);} }
